export function reservationPrintTitle(mode: ReservationPrintMode, status?: string | null): string {
  if (mode === "draft") return DRAFT_RESERVATION_PRINT_TITLE;
  if (status === "confirmed") return BOOKING_CONFIRMATION_PRINT_TITLE;
  return RESERVATION_SUMMARY_PRINT_TITLE;
}

export function printableText(value: string | number | null | undefined): string | null {
  if (value == null) return null;
  const text = String(value).trim();
  if (!text || text === "—" || text === "-") return null;
  if (UUID_RE.test(text)) return null;
  return text;
}

export function formatPropertyContactAddress(
  parts: Array<string | null | undefined>,
): string | null {
  const text = parts
    .map((part) => part?.trim() ?? "")
    .filter(Boolean)
    .join(", ");
  return text || null;
}

export function formatPrintDate(value: string | null | undefined): string | null {
  const text = printableText(value);
  if (!text) return null;
  const day = text.slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return text;
  const parsed = new Date(`${day}T00:00:00`);
  if (Number.isNaN(parsed.getTime())) return text;
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  }).format(parsed);
}

export function formatPrintDateTime(value: string | Date | null | undefined): string | null {
  if (value == null) return null;
  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return null;
    return new Intl.DateTimeFormat("en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    }).format(value);
  }
  const text = printableText(value);
  if (!text) return null;
  if (!/^\d{4}-\d{2}-\d{2}T/.test(text)) return text;
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return text;
  return formatPrintDateTime(parsed);
}

export function confirmedTimestampFromHistory(
  history: Array<{
    eventType: string;
    createdAt: string | null;
    newValues: { status?: string | null } | null;
  }>,
): string | null {
  const match = history.find(
    (entry) =>
      entry.eventType === "status_changed" &&
      entry.newValues?.status === "confirmed" &&
      Boolean(entry.createdAt?.trim()),
  );
  return match?.createdAt ?? null;
}

export function buildDraftReservationPrintData(
  input: DraftReservationPrintInput,
): ReservationPrintDocumentData {
  const noShow = reviewNoShowCopy(input.noShowPolicy, input.noShowPenalty);
  const refundability = reviewRefundabilityCopy(input.refundabilityKind, input.refundabilityLabel);
  return assemblePrintDocument({
    mode: "draft",
    status: null,
    generatedAt: input.generatedAt,
    propertyName: input.propertyName,
    propertyAddress: input.propertyAddress,
    propertyPhone: input.propertyPhone,
    propertyEmail: input.propertyEmail,
    propertyWebsite: input.propertyWebsite,
    confirmationNumber: null,
    createdAt: null,
    confirmedAt: null,
    guestName: input.guestName,
    phone: input.phone,
    email: input.email,
    nationality: input.nationality,
    idDocumentNumber: input.idDocumentNumber,
    bookedBy: input.bookedBy,
    bookingSource: input.bookingSource,
    salesChannel: input.salesChannel,
    marketSegment: input.marketSegment,
    companyName: input.companyName,
    travelAgentName: input.travelAgentName,
    groupName: input.groupName,
    checkIn: input.arrivalLabel,
    checkOut: input.departureLabel,
    nights: input.nights,
    rooms: input.rooms,
    adults: input.adults,
    children: input.children,
    infants: input.infants,
    roomImageUrl: input.roomImageUrl,
    roomName: input.roomName,
    roomCode: input.roomCode,
    ratePlan: input.ratePlan,
    inclusions: input.inclusions,
    ratePerNight: input.ratePerNight,
    roomTotal: input.roomTotal,
    packages: input.packages,
    packagesKnown: true,
    packagesTotal: null,
    paymentType: input.paymentType,
    paymentMethod: input.paymentMethod,
    depositRequired: input.depositRequired,
    depositAmount: input.depositAmount,
    depositDueDate: formatPrintDate(input.depositDueDate) ?? printableText(input.depositDueDate),
    paymentTerms: draftPaymentTerms(input),
    cancellation: input.cancellation,
    noShow,
    earlyDeparture: input.earlyDeparture,
    refundability,
    preferences: input.preferences,
    serviceRequests: input.serviceRequests,
    specialRequests: input.specialRequests,
    roomAssignment: input.roomAssignment,
  });
}

