function assemblePrintDocument(input: {
  mode: ReservationPrintMode;
  status: string | null;
  generatedAt: string;
  propertyName: string;
  propertyAddress?: string | null;
  propertyPhone?: string | null;
  propertyEmail?: string | null;
  propertyWebsite?: string | null;
  confirmationNumber: string | null;
  createdAt: string | null;
  confirmedAt: string | null;
  guestName: string | null;
  phone: string | null;
  email: string | null;
  nationality: string | null;
  idDocumentNumber: string | null;
  bookedBy: string | null;
  bookingSource: string | null;
  salesChannel: string | null;
  marketSegment: string | null;
  companyName: string | null;
  travelAgentName: string | null;
  groupName: string | null;
  checkIn: string | null;
  checkOut: string | null;
  nights: number | null;
  rooms: number | null;
  adults: number | null;
  children: number | null;
  infants: number | null;
  roomImageUrl: string | null;
  roomName: string | null;
  roomCode: string | null;
  ratePlan: string | null;
  inclusions: string | null;
  ratePerNight: string | null;
  roomTotal: string | null;
  packages: ReservationPrintPackageInput[];
  packagesKnown: boolean;
  packagesTotal: string | null;
  paymentType: string | null;
  paymentMethod: string | null;
  depositRequired: string | null;
  depositAmount: string | null;
  depositDueDate: string | null;
  paymentTerms: string[];
  cancellation: string | null;
  noShow: string | null;
  earlyDeparture: string | null;
  refundability: string | null;
  preferences: string[];
  serviceRequests: string[];
  specialRequests: string | null;
  roomAssignment: string | null;
}): ReservationPrintDocumentData {
  const roomTotal = printableText(input.roomTotal);
  const packages = input.packages.flatMap((row) => {
    const description = printableText(row.name);
    if (!description) return [];
    return [
      {
        description,
        quantity: packageQuantity(row.chargeBasis, row.quantity),
        price: printableText(row.unitAmount),
        amount: printableText(row.amount),
        inclusions: printableText(row.inclusions),
      },
    ];
  });
  const payment = lines(
    line("Payment Type", input.paymentType),
    line("Payment Method", input.paymentMethod),
    line("Deposit Required", input.depositRequired),
    line("Deposit Amount", input.depositAmount),
    line("Deposit Due Date", input.depositDueDate),
    ...input.paymentTerms.map((term) => line("Payment Terms", term)),
  );
  return {
    mode: input.mode,
    title: reservationPrintTitle(input.mode, input.status),
    propertyName: printableText(input.propertyName) ?? "Property",
    propertyAddress: printableText(input.propertyAddress),
    propertyPhone: printableText(input.propertyPhone),
    propertyEmail: printableText(input.propertyEmail),
    propertyWebsite: printableText(input.propertyWebsite),
    showDraftBadge: input.mode === "draft",
    confirmationNumber: input.mode === "draft" ? null : printableText(input.confirmationNumber),
    statusLabel: input.mode === "draft" ? null : statusLabel(input.status),
    generatedAt: printableText(input.generatedAt) ?? "",
    createdAt: input.mode === "draft" ? null : printableText(input.createdAt),
    confirmedAt: input.mode === "draft" ? null : printableText(input.confirmedAt),
    guest: lines(
      line("Name", input.guestName),
      line("Phone", input.phone),
      line("Email", input.email),
      line("Nationality", input.nationality),
      line("ID / Passport", maskIdNumber(input.idDocumentNumber)),
    ),
    booking: lines(
      line("Booked by", input.bookedBy),
      line("Booking Source", input.bookingSource),
      line("Channel", input.salesChannel),
      line("Market Segment", input.marketSegment),
      line("Company", input.companyName),
      line("Travel Agency", input.travelAgentName),
      line("Group", input.groupName),
    ),
    stay: lines(
      line("Check-in", input.checkIn),
      line("Check-out", input.checkOut),
      line("Nights", countText(input.nights)),
      line("Rooms", countText(input.rooms)),
      line("Adults", countText(input.adults)),
      line("Children", countText(input.children)),
      line("Infants", countText(input.infants)),
    ),
    room: {
      imageUrl: printableText(input.roomImageUrl),
      typeName: printableText(input.roomName),
      code: printableText(input.roomCode),
      ratePlan: printableText(input.ratePlan),
      inclusions: printableText(input.inclusions),
      ratePerNight: printableText(input.ratePerNight),
      nights: countText(input.nights),
      roomTotal,
    },
    packages,
    packagesKnown: input.packagesKnown,
    roomTotal,
    packagesTotal: printableText(input.packagesTotal),
    reservationTotal: null,
    payment,
    policies: lines(
      line("Cancellation", input.cancellation),
      line("No-show", input.noShow),
      line("Early Departure", input.earlyDeparture),
      line("Refundability", input.refundability),
    ),
    preferences: input.preferences
      .map((row) => printableText(row))
      .filter((row): row is string => Boolean(row)),
    serviceRequests: input.serviceRequests
      .map((row) => printableText(row))
      .filter((row): row is string => Boolean(row)),
    specialRequests: printableText(input.specialRequests),
    roomAssignment: printableText(input.roomAssignment),
    footer:
      input.mode === "draft" ? DRAFT_RESERVATION_PRINT_FOOTER : PERSISTED_RESERVATION_PRINT_FOOTER,
  };
}

function draftPaymentTerms(input: DraftReservationPrintInput): string[] {
  const linesOut: string[] = [];
  const company = printableText(input.companyName);
  const agent = printableText(input.travelAgentName);
  if (company) {
    linesOut.push(
      printableText(input.companyTerms) || `No payment terms configured for ${company}`,
    );
  }
  if (agent) {
    linesOut.push(
      printableText(input.travelAgentTerms) || `No payment terms configured for ${agent}`,
    );
  }
  return linesOut;
}

function packageQuantity(chargeBasis: string | null, quantity: number | null): string | null {
  const basis = printableText(chargeBasis);
  const basisLabel = basis ? (CHARGE_BASIS_LABELS[basis] ?? basis) : null;
  if (quantity != null && Number.isFinite(quantity)) {
    return basisLabel ? `${quantity} · ${basisLabel}` : String(quantity);
  }
  return basisLabel;
}

function statusLabel(status: string | null): string | null {
  if (!status) return null;
  return STATUS_LABELS[status] ?? printableText(status.replaceAll("_", " "));
}

function countText(value: number | null): string | null {
  if (value == null || !Number.isFinite(value)) return null;
  return String(value);
}

function line(label: string, value: string | null | undefined): ReservationPrintLine | null {
  const text = printableText(value);
  if (!text) return null;
  return { label, value: text };
}

function lines(...items: Array<ReservationPrintLine | null>): ReservationPrintLine[] {
  return items.filter((item): item is ReservationPrintLine => item != null);
}
